use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let input = input.as_array();
    if input.len() != 2 {
        return serde_json::Value::Error("Input must be a list with two arrays.");
    }

    let left = input[0].as_array();
    let right = input[1].as_array();

    let mut result = Vec::new();
    let mut left_index = 0;
    let mut right_index = 0;

    while left_index < left.len() && right_index < right.len() {
        let left_key = left[left_index][0];
        let right_key = right[right_index][0];

        if left_key == right_key {
            result.push(vec![left_key, left[left_index][1], right[left_index][1]]);
            left_index += 1;
            right_index += 1;
        } else if left_key < right_key {
            left_index += 1;
        } else {
            right_index += 1;
        }
    }

    serde_json::Value::Array(result)
}

fn main() {
    let input = serde_json::Value::from_json_str("{\"input\":[[[2,9],[1,4]],[[2,3],[3,8]]],"expected":[[2,9,3]]}]");
    let result = solve(input);
    println!("{:?}", result);
}
